?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($title)?> | Ideal Muscat Admin</title><link rel="stylesheet" href="assets/theme.css"><link rel="stylesheet" href="assets/admin.css"></head><body class="<?=$logged?'panel':'auth-page'?>">
<?php if($logged):?><button class="sidebar-backdrop" aria-label="Close navigation" tabindex="-1"></button><aside class="admin-sidebar" id="admin-sidebar"><a class="admin-brand" href="index.php"><span class="brand-mark">IM</span><span>Ideal Muscat<small>Company workspace</small></span></a><p class="nav-caption">WORKSPACE</p><nav><?php foreach(['index.php'=>['Dashboard','grid'],'settings.php'=>['Company settings','settings'],'entries.php'=>['Website content','file'],'messages.php'=>['Enquiries','mail']] as $url=>$data):?><a class="sidebar-link <?=$page===$url?'selected':''?>" href="<?=e($url)?>" <?=$page===$url?'aria-current="page"':''?>><?=icon($data[1])?><span><?=e($data[0])?></span></a><?php endforeach;?></nav><div class="sidebar-bottom"><p>Ready to review your website?</p><a class="btn-company" href="../index.php">View website ↗</a><form method="post" action="logout.php"><?=token()?><button class="logout-button">Log out</button></form></div></aside><div class="admin-workspace"><header class="admin-toolbar"><button class="sidebar-toggle" aria-controls="admin-sidebar" aria-expanded="false" aria-label="Open navigation"><?=icon('menu')?></button><span>Company administration</span><div class="toolbar-right"><a href="../index.php">View website ↗</a><span class="admin-avatar" aria-label="Administrator">AD</span></div></header><main class="admin-wrap"><div class="page-heading"><div><p class="eyebrow">IDEAL MUSCAT RANCHES</p><h1><?=e($title)?></h1></div><span class="workspace-pill">Company workspace</span></div><?php else:?><main class="admin-wrap auth-card"><a class="admin-brand" href="../index.php"><span class="brand-mark">IM</span><span>Ideal Muscat<small>Company administration</small></span></a><h1><?=e($title)?></h1><p class="auth-description">Sign in to manage your company website.</p><?php endif;
}
function icon(string $name): string {
$paths=['grid'=>'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>','file'=>'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>','mail'=>'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>','settings'=>'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>','menu'=>'<path d="M4 6h16M4 12h16M4 18h16"/>'];
return '<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??$paths['file']).'</svg>';
}
